function makeCharParams(text, baseSize, overrides = []) {
  return Array.from(text).map((_, index) => ({
    dx: overrides[index]?.dx ?? 0,
    dy: overrides[index]?.dy ?? 0,
    size: overrides[index]?.size ?? baseSize
  }));
}

// Tweakpane v3：テキストの位置・サイズと文字ごとの位置を動かす UI
function setupPane() {
  const pane = new Tweakpane.Pane({ title: 'テキスト調整' });
  const refresh = () => {
    buildStatic();
    redraw();
  };
  pane.addSeparator();
  pane.addInput(params, 'titleX', { min: 0, max: A4_W, step: 1 }).on('change', refresh);
  pane.addInput(params, 'titleY', { min: 0, max: A4_H, step: 1 }).on('change', refresh);
  pane.addInput(params, 'titleSize', { min: 8, max: 220, step: 1 }).on('change', refresh);
  addCharPane(pane, 'title', refresh);

  pane.addSeparator();
  pane.addInput(params, 'infoX', { min: 0, max: A4_W, step: 1 }).on('change', refresh);
  pane.addInput(params, 'infoY', { min: 0, max: A4_H, step: 1 }).on('change', refresh);
  pane.addInput(params, 'infoSize', { min: 8, max: 120, step: 1 }).on('change', refresh);
  addCharPane(pane, 'info', refresh);

  pane.addSeparator();
  pane.addInput(params, 'flowX', { min: 0, max: A4_W, step: 1 }).on('change', refresh);
  pane.addInput(params, 'flowY', { min: 0, max: A4_H, step: 1 }).on('change', refresh);
  pane.addInput(params, 'flowSize', { min: 8, max: 220, step: 1 }).on('change', refresh);
  addCharPane(pane, 'flow', refresh);
  pane.addButton({ title: '情報をコピー' }).on('click', copyInfo);
}

function addCharPane(pane, key, refresh) {
  const run = TEXT_RUNS[key];
  const folder = pane.addFolder({ title: `${run.label} 文字別` });
  const chars = params[`${key}Chars`];
  const moveRange = key === 'flow' ? 360 : 240;
  const sizeMax = key === 'flow' ? 180 : 120;
  chars.forEach((charParams, index) => {
    const ch = Array.from(run.text)[index];
    const label = ch === ' ' ? 'space' : ch;
    folder.addInput(charParams, 'dx', {
      label: `${index + 1} ${label} x`,
      min: -moveRange,
      max: moveRange,
      step: 1
    }).on('change', refresh);
    folder.addInput(charParams, 'dy', {
      label: `${index + 1} ${label} y`,
      min: -moveRange,
      max: moveRange,
      step: 1
    }).on('change', refresh);
    folder.addInput(charParams, 'size', {
      label: `${index + 1} ${label} size`,
      min: 4,
      max: sizeMax,
      step: 1
    }).on('change', refresh);
  });
}

// 現在のテキスト設定をクリップボードにコピー（チャットに貼り付け用）
function copyInfo() {
  const text = JSON.stringify(params, null, 2);
  navigator.clipboard.writeText(text);
  console.log('コピーしました:\n' + text);
}

// 建物・色の状態をクリップボードにコピー
function copyState() {
  const state = {
    usePink,
    colors,
    buildings: buildings.map(b => ({
      x: b.x, w: b.w, h: b.h,
      c: b.c, c2: b.c2,
      hasWindows: b.hasWindows,
      windows: b.windows,
      rows: b.rows
    }))
  };
  const text = JSON.stringify(state);
  navigator.clipboard.writeText(text);
  console.log('状態をコピーしました');
}

function switchVersion(stateData, flowParams) {
  // 現バッファを prev に退避（フェード用）
  prevCityBuf.clear(); prevCityBuf.image(cityBuf, 0, 0);
  prevReflBuf.clear(); prevReflBuf.image(reflectionBuf, 0, 0);

  params.flowY = flowParams.flowY;
  flowParams.flowChars.forEach((c, i) => {
    params.flowChars[i].dx   = c.dx;
    params.flowChars[i].dy   = c.dy;
    params.flowChars[i].size = c.size;
  });
  applyState(stateData);

  // 先焼きバッファからコピー（buildCity/buildReflection は不要）
  const isBlue = stateData === FIXED_STATE_BLUE;
  cityBuf.clear();
  cityBuf.image(isBlue ? blueCityBuf : pinkCityBuf, 0, 0);
  reflectionBuf.clear();
  reflectionBuf.image(isBlue ? blueReflBuf : pinkReflBuf, 0, 0);

  buildStatic();
  fadeProgress = 0;
  fading = true;
  loop();
}
function switchToBlue() { currentVersion = 'blue'; switchVersion(FIXED_STATE_BLUE, FLOW_BLUE); }
function switchToPink() { currentVersion = 'pink'; switchVersion(FIXED_STATE_PINK, FLOW_PINK); }

function startMoveAnim() {
  if (animating) return;
  if (currentVersion === 'blue') {
    // 建物を即座に pink に切り替え、テキストは blue 位置からアニメーション
    switchVersion(FIXED_STATE_PINK, FLOW_PINK);
    params.flowY = FLOW_BLUE.flowY;
    FLOW_BLUE.flowChars.forEach((c, i) => {
      params.flowChars[i].dx   = c.dx;
      params.flowChars[i].dy   = c.dy;
      params.flowChars[i].size = c.size;
    });
    animFromFlow = FLOW_BLUE;
    animToFlow   = FLOW_PINK;
    currentVersion = 'pink';
  } else {
    switchVersion(FIXED_STATE_BLUE, FLOW_BLUE);
    params.flowY = FLOW_PINK.flowY;
    FLOW_PINK.flowChars.forEach((c, i) => {
      params.flowChars[i].dx   = c.dx;
      params.flowChars[i].dy   = c.dy;
      params.flowChars[i].size = c.size;
    });
    animFromFlow = FLOW_PINK;
    animToFlow   = FLOW_BLUE;
    currentVersion = 'blue';
  }
  rebuildTextBuf();
  animProgress = 0;
  animating    = true;
  loop();
}

function rebuildTextBuf() {
  if (!textBuf) textBuf = createGraphics(width, height);
  textBuf.clear();
  textBuf.noStroke();
  textBuf.fill(20);
  textBuf.textFont(titleFont);
  drawTextRun(textBuf, 'title', params.titleX, params.titleY, params.titleSize, params.titleChars);
  drawTextRun(textBuf, 'info',  params.infoX,  params.infoY,  params.infoSize,  params.infoChars);
  drawTextRun(textBuf, 'flow',  params.flowX,  params.flowY,  params.flowSize,  params.flowChars);
}

function easeInOut(t) {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

function updateMotionGrid() {
  if (!vidReady || vid.width === 0) return;
  let cr = width / height, vw = vid.width, vh = vid.height, sw, sh;
  if (vw / vh > cr) { sh = vh; sw = sh * cr; } else { sw = vw; sh = sw / cr; }
  const sx = (vw - sw) / 2, sy = (vh - sh) / 2;
  motionCapBuf.clear();
  // 動画全体をグリッドサイズに縮小してキャプチャ（確実に動作する方式）
  motionCapBuf.image(vid, 0, 0, MG_COLS, MG_ROWS, sx, sy, sw, sh);
  motionCapBuf.loadPixels();
  const pixels = motionCapBuf.pixels;
  if (!pixels || pixels.length === 0) return;
  // pixels.length = (MG_COLS*pd) * (MG_ROWS*pd) * 4 なので pd = sqrt(length / (W*H*4))
  const pd = max(1, round(sqrt(pixels.length / (MG_COLS * MG_ROWS * 4))));
  const actualW = MG_COLS * pd;
  if (prevMotionPixels && pixels.length === prevMotionPixels.length) {
    const frameDiffs = new Float32Array(MG_COLS * MG_ROWS);
    let diffSum = 0;
    for (let row = 0; row < MG_ROWS; row++) {
      for (let col = 0; col < MG_COLS; col++) {
        const px = min(floor((col + 0.5) * pd), actualW - 1);
        const py = min(floor((row + 0.5) * pd), MG_ROWS * pd - 1);
        const i = (py * actualW + px) * 4;
        const diff = (abs(pixels[i]     - prevMotionPixels[i])     +
                      abs(pixels[i + 1] - prevMotionPixels[i + 1]) +
                      abs(pixels[i + 2] - prevMotionPixels[i + 2])) / (3 * 255);
        const gi = row * MG_COLS + col;
        frameDiffs[gi] = diff;
        diffSum += diff;
      }
    }
    const diffMean = diffSum / frameDiffs.length;
    for (let gi = 0; gi < frameDiffs.length; gi++) {
      const localDiff = max(0, frameDiffs[gi] - diffMean * 0.85);
      motionGrid[gi] = max(motionGrid[gi] * 0.82, localDiff * 8.0);
    }
  }
  let maxMotion = 0;
  for (const v of motionGrid) {
    if (v > maxMotion) maxMotion = v;
  }
  window.__motionDebug = window.__motionDebug || {};
  window.__motionDebug.maxMotion = maxMotion;
  window.__motionDebug.gridReady = true;
  prevMotionPixels = new Uint8ClampedArray(pixels);
}

function drawMotionEffect() {
  const cx = width / 2, cy = height / 2;
  const seedThreshold = 0.004;
  const minBoxArea = 14;
  const maxBoxArea = width * height * 0.18;
  const gx = c => (c / MG_COLS) * width;
  const gy = r => (r / MG_ROWS) * height;
  const inMask = (x, y) => y >= cy && ((x - cx) ** 2 + (y - cy) ** 2 <= MASK_R * MASK_R);

  // 検出は一定フレーム間隔ごとに再計算し、結果をキャッシュして描画負荷を下げる
  let emittedBoxes = motionBoxes || [];
  if (frameCount % MOTION_UPDATE_INTERVAL === 0) {
    const candidates = [];
    for (let row = 0; row < MG_ROWS; row++) {
      for (let col = 0; col < MG_COLS; col++) {
        const gi = row * MG_COLS + col;
        const value = motionGrid[gi];
        if (value <= seedThreshold) continue;
        const x = gx(col + 0.5);
        const y = gy(row + 0.5);
        if (!inMask(x, y)) continue;

        let isPeak = true;
        for (let dr = -1; dr <= 1 && isPeak; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = row + dr;
            const nc = col + dc;
            if (nr < 0 || nr >= MG_ROWS || nc < 0 || nc >= MG_COLS) continue;
            if (motionGrid[nr * MG_COLS + nc] > value) {
              isPeak = false;
              break;
            }
          }
        }
        if (isPeak) candidates.push({ row, col, value });
      }
    }

    candidates.sort((a, b) => b.value - a.value);
    emittedBoxes = [];
    // 上位 N 個だけをボックス化（数を減らして見やすくする）
    for (const c of candidates.slice(0, 6)) {
      const centerX = gx(c.col + 0.5);
      const centerY = gy(c.row + 0.5);
      // サイズに多様性を追加: 値に応じた基本サイズにランダム性を加え、
      // ごく稀に非常に大きい/小さいボックスを生成
      // 基本サイズをやや控えめにして最大値を下げる
      let size = constrain(5 + pow(c.value, 0.6) * 40 + random(-6, 6), 3, 60);
      const r = random();
      if (r < 0.04) {
        // 大きめボックス (4%)
        size = constrain(size * random(1.1, 1.3), 8, 90);
      } else if (r < 0.64) {
        // 小さめボックス (60%)
        size = constrain(size * random(0.2, 0.55), 2, 40);
      }
      const aspect = 0.6 + c.value * 0.3 + random(-0.12, 0.12);
      const halfW = size * aspect * 0.5;
      const halfH = size * 0.5;
      const x1 = centerX - halfW;
      const y1 = centerY - halfH;
      const x2 = centerX + halfW;
      const y2 = centerY + halfH;
      if ((x2 - x1) * (y2 - y1) < minBoxArea) continue;
      if ((x2 - x1) * (y2 - y1) > maxBoxArea) continue;
      emittedBoxes.push({ x1, y1, x2, y2 });
    }

    window.__motionDebug = window.__motionDebug || {};
    window.__motionDebug.detectedCount = candidates.length;
    window.__motionDebug.emittedCount = emittedBoxes.length;
    window.__motionDebug.emittedPreview = emittedBoxes.slice(0, 8).map(d => ({
      x1: d.x1,
      y1: d.y1,
      x2: d.x2,
      y2: d.y2,
      w: d.x2 - d.x1,
      h: d.y2 - d.y1
    }));

    // キャッシュに保存
    motionBoxes = emittedBoxes;
  }

  // --- 追跡ロジック: emittedBoxes を既存の trackedBoxes にマッチングして追従させる ---
  // trackedBoxes: {x1,y1,x2,y2,tx1,ty1,tx2,ty2,age,alpha}
  const MAX_AGE = MOTION_UPDATE_INTERVAL * 6;
  if (!trackedBoxes) trackedBoxes = [];
  if (frameCount % MOTION_UPDATE_INTERVAL === 0) {
    // マッチング（近傍の trackedBoxes に割り当て）
    const used = new Array(trackedBoxes.length).fill(false);
    const newTracked = [];
    for (const e of emittedBoxes) {
      const ecx = (e.x1 + e.x2) * 0.5;
      const ecy = (e.y1 + e.y2) * 0.5;
      const ew = e.x2 - e.x1;
      const eh = e.y2 - e.y1;
      let bestIdx = -1;
      let bestDist = Infinity;
      for (let i = 0; i < trackedBoxes.length; i++) {
        if (used[i]) continue;
        const t = trackedBoxes[i];
        const tcx = (t.x1 + t.x2) * 0.5;
        const tcy = (t.y1 + t.y2) * 0.5;
        const d = dist(ecx, ecy, tcx, tcy);
        if (d < bestDist) { bestDist = d; bestIdx = i; }
      }
      const matchThreshold = max(ew, eh) * 1.2 + 20;
      if (bestIdx >= 0 && bestDist <= matchThreshold) {
        // マッチ: ターゲットを更新して age をリセット
        const t = trackedBoxes[bestIdx];
        t.tx1 = e.x1; t.ty1 = e.y1; t.tx2 = e.x2; t.ty2 = e.y2;
        t.age = 0;
        t.alpha = 1.0;
        used[bestIdx] = true;
        newTracked.push(t);
      } else {
        // 新しいトラックを追加
        newTracked.push({
          x1: e.x1, y1: e.y1, x2: e.x2, y2: e.y2,
          tx1: e.x1, ty1: e.y1, tx2: e.x2, ty2: e.y2,
          age: 0, alpha: 1.0
        });
      }
    }

    // 使われなかった古い trackedBoxes は継続（fade 対象）
    for (let i = 0; i < trackedBoxes.length; i++) {
      if (!used[i]) {
        const t = trackedBoxes[i];
        t.age = (t.age || 0) + 1;
        // ターゲットは現状維持（徐々にフェード）
        t.tx1 = t.tx1 ?? t.x1; t.ty1 = t.ty1 ?? t.y1;
        t.tx2 = t.tx2 ?? t.x2; t.ty2 = t.ty2 ?? t.y2;
        // 減衰させていく
        t.alpha = max(0, (t.alpha ?? 1.0) - 0.12);
        if ((t.age || 0) < MAX_AGE && t.alpha > 0.02) newTracked.push(t);
      }
    }

    trackedBoxes = newTracked;
  }

  // 毎フレーム、trackedBoxes を補間して滑らかに動かす
  for (const t of trackedBoxes) {
    const interp = 0.28; // 補間率（0〜1）: 小さいほど遅く追従
    t.x1 = lerp(t.x1 ?? t.tx1, t.tx1, interp);
    t.y1 = lerp(t.y1 ?? t.ty1, t.ty1, interp);
    t.x2 = lerp(t.x2 ?? t.tx2, t.tx2, interp);
    t.y2 = lerp(t.y2 ?? t.ty2, t.ty2, interp);
    // 徐々に薄くする（存在感を残すために最小 α を維持）
    t.alpha = min(1.0, t.alpha ?? 1.0);
  }

  push();
  noFill();
  stroke(0);
  strokeWeight(1);
  for (const t of trackedBoxes) {
    const boxW = t.x2 - t.x1;
    const boxH = t.y2 - t.y1;
    if (boxW <= 0 || boxH <= 0) continue;
    const a = typeof t.alpha === 'number' ? t.alpha : 1.0;
    stroke(0, round(255 * a));
    rect(t.x1 - 2, t.y1 - 2, boxW + 4, boxH + 4);
  }
  window.__motionDebug.drawnCount = trackedBoxes.length;
  pop();
}

function applyState(state) {
  usePink = state.usePink;
  colors = state.colors;
  buildings = state.buildings.map(d => {
    const b = Object.create(Bs.prototype);
    Object.assign(b, d);
    return b;
  });
}

// コピーした状態を貼り付けて同じ街を再現
function loadStatePrompt() {
  const json = prompt('コピーした状態を貼り付けてください:');
  if (!json) return;
  try {
    applyState(JSON.parse(json));
    buildCity();
    if (vidReady) buildReflection();
    buildStatic();
    redraw();
  } catch (e) {
    console.error('読み込み失敗:', e);
  }
}

// 右側に固定表示するボタンを作る
function makeButton(label, topCss, onClick) {
  const btn = createButton(label);
  btn.style('position', 'fixed');
  btn.style('top', topCss);
  btn.style('right', '24px');
  btn.style('transform', 'translateY(-50%)');
  btn.style('padding', '10px 16px');
  btn.style('background', '#111');
  btn.style('color', '#fff');
  btn.style('border', 'none');
  btn.style('border-radius', '4px');
  btn.style('font-family', 'sans-serif');
  btn.style('font-size', '12px');
  btn.style('letter-spacing', '0.08em');
  btn.style('cursor', 'pointer');
  btn.mousePressed(onClick);
}

function onVideoReady() {
  vidReady = true;
  captureStill();

  // blue reflection 先焼き
  applyState(FIXED_STATE_BLUE);
  buildReflection();
  blueReflBuf.clear();
  blueReflBuf.image(reflectionBuf, 0, 0);

  // pink reflection 先焼き
  applyState(FIXED_STATE_PINK);
  buildReflection();
  pinkReflBuf.clear();
  pinkReflBuf.image(reflectionBuf, 0, 0);

  // 現バージョンに戻す
  const isBlue = currentVersion === 'blue';
  applyState(isBlue ? FIXED_STATE_BLUE : FIXED_STATE_PINK);
  reflectionBuf.clear();
  reflectionBuf.image(isBlue ? blueReflBuf : pinkReflBuf, 0, 0);

  buildStatic();
  redraw();
}

function generateCity() {
  newColors();
  n = 50;
  buildings = [];
  const slotW = (2 * MASK_R) / n;
  for (let i = 0; i < n; i++) {
    // 円の幅を n 等分し、各スロットに1棟ずつ。ジッター大きめで場所により密集する
    const cx = -MASK_R + slotW * (i + 0.5) + random(-slotW * 0.9, slotW * 0.9);
    buildings.push(new Bs(cx));
  }
  buildCity();
}

// 上半分：main の点描シティスケープ（パレット色）を一度だけ焼き付ける
function buildCity() {
  cityBuf.clear();
  cityBuf.noStroke();
  cityBuf.push();
  cityBuf.translate(width / 2, height / 2);
  for (const b of buildings) {
    b.display(cityBuf, -1, null);
  }
  cityBuf.pop();
}

// 下半分：動画の静止画を、同じ点描で描いた反射を焼き付ける
function buildReflection() {
  reflectionBuf.clear();
  reflectionBuf.noStroke();
  stillFrame.loadPixels();
  reflectionBuf.push();
  reflectionBuf.translate(width / 2, height / 2);
  for (const b of buildings) {
    b.display(reflectionBuf, 1, sampleStill);
  }
  reflectionBuf.pop();
}

// 動画の現在フレームを中央クロップして静止画にする
function captureStill() {
  let canvasRatio = width / height;
  let sw, sh;
  if (vid.width / vid.height > canvasRatio) {
    sh = vid.height;
    sw = sh * canvasRatio;
  } else {
    sw = vid.width;
    sh = sw / canvasRatio;
  }
  let sx = (vid.width - sw) / 2;
  let sy = (vid.height - sh) / 2;
  videoBuf.image(vid, 0, 0, width, height, sx, sy, sw, sh);
  stillFrame = videoBuf.get();
}

// 静止画の色を、原点中央の座標系から取得する
function sampleStill(x, y) {
  return stillFrame.get(
    constrain(floor(width / 2 + x), 0, width - 1),
    constrain(floor(height / 2 + y), 0, height - 1)
  );
}

// 点描の静止部分（上半分シティ＋下半分反射）を staticBuf に焼き付け、
// テキストのみ textBuf に別途焼き付ける
function buildStatic() {
  // 点描レイヤー
  const g = staticBuf;
  g.background(255);
  g.drawingContext.save();
  try {
    g.drawingContext.beginPath();
    g.drawingContext.arc(width / 2, height / 2, MASK_R, 0, TWO_PI);
    g.drawingContext.clip();
    g.image(cityBuf, 0, 0);
    g.image(reflectionBuf, 0, 0);
  } catch (e) {
    console.error(e);
  }
  g.drawingContext.restore();

  // テキストレイヤー（動画の上に重ねるため別バッファ）
  if (!textBuf) textBuf = createGraphics(width, height);
  textBuf.clear();
  textBuf.noStroke();
  textBuf.fill(20);
  textBuf.textFont(titleFont);
  drawTextRun(textBuf, 'title', params.titleX, params.titleY, params.titleSize, params.titleChars);
  drawTextRun(textBuf, 'info', params.infoX, params.infoY, params.infoSize, params.infoChars);
  drawTextRun(textBuf, 'flow', params.flowX, params.flowY, params.flowSize, params.flowChars);
}

function drawTextRun(g, key, x, y, baseSize, charParams) {
  const run = TEXT_RUNS[key];
  const chars = Array.from(run.text);
  const widths = chars.map((ch) => {
    g.textSize(baseSize);
    return g.textWidth(ch);
  });
  const totalWidth = widths.reduce((sum, width) => sum + width, 0);
  let cursorX = run.anchor === 'center' ? x - totalWidth / 2 : x;

  // オフセットの基準を各文字の中心にする
  const topY = run.anchor === 'center' ? y - baseSize : y;
  g.textAlign(CENTER, CENTER);
  chars.forEach((ch, index) => {
    const offset = charParams[index] || { dx: 0, dy: 0, size: baseSize };
    const charSize = offset.size ?? baseSize;
    const boxCenterX = cursorX + widths[index] / 2;
    const boxCenterY = topY + baseSize / 2;
    const drawX = boxCenterX + offset.dx;
    const drawY = boxCenterY + offset.dy;
    g.textSize(charSize);
    g.text(ch, drawX, drawY);
    cursorX += widths[index];
  });
}

function draw() {
  // テキストアニメーション
  if (animating) {
    animProgress = min(animProgress + 1 / ANIM_FRAMES, 1);
    const t = easeInOut(animProgress);
    params.flowY = lerp(animFromFlow.flowY, animToFlow.flowY, t);
    animFromFlow.flowChars.forEach((from, i) => {
      const to = animToFlow.flowChars[i];
      params.flowChars[i].dx   = lerp(from.dx,   to.dx,   t);
      params.flowChars[i].dy   = lerp(from.dy,   to.dy,   t);
      params.flowChars[i].size = lerp(from.size, to.size, t);
    });
    rebuildTextBuf();
    if (animProgress >= 1) animating = false;
  }

  // 建物フェード進行
  if (fading) {
    fadeProgress = min(fadeProgress + 1 / FADE_FRAMES, 1);
    if (fadeProgress >= 1) fading = false;
  }
  const ft = fading ? easeInOut(fadeProgress) : 1;

  if (frameCount % 2 === 0) updateMotionGrid();

  background(255);
  drawBottomParticles();

  drawingContext.save();
  try {
    drawingContext.beginPath();
    drawingContext.arc(width / 2, height / 2, MASK_R, 0, TWO_PI);
    drawingContext.clip();

    // 上半分：シティドット（フェード）
    if (fading) {
      tint(255, round((1 - ft) * 255)); image(prevCityBuf, 0, 0); noTint();
      tint(255, round(ft * 255));       image(cityBuf, 0, 0);     noTint();
    } else {
      image(cityBuf, 0, 0);
    }

    // 下半分：動画＋リフレクション（フェード）
    let cr = width / height, vw = vid.width, vh = vid.height, sw, sh;
    if (vw / vh > cr) { sh = vh; sw = sh * cr; } else { sw = vw; sh = sw / cr; }
    const sx = (vw - sw) / 2, sy = (vh - sh) / 2;

    if (vidReady) {
      // 現在の建物でマスクした動画
      vidMaskBuf.clear();
      vidMaskBuf.image(vid, 0, 0, width, height, sx, sy, sw, sh);
      vidMaskBuf.drawingContext.globalCompositeOperation = 'destination-in';
      vidMaskBuf.image(reflectionBuf, 0, 0);
      vidMaskBuf.drawingContext.globalCompositeOperation = 'source-over';

      if (fading) {
        // 旧建物でマスクした動画
        prevVidMaskBuf.clear();
        prevVidMaskBuf.image(vid, 0, 0, width, height, sx, sy, sw, sh);
        prevVidMaskBuf.drawingContext.globalCompositeOperation = 'destination-in';
        prevVidMaskBuf.image(prevReflBuf, 0, 0);
        prevVidMaskBuf.drawingContext.globalCompositeOperation = 'source-over';

        tint(255, round((1 - ft) * 255)); image(prevVidMaskBuf, 0, 0); noTint();
        tint(255, round(ft * 255));       image(vidMaskBuf, 0, 0);     noTint();
      } else {
        image(vidMaskBuf, 0, 0);
      }
    } else {
      if (fading) {
        tint(255, round((1 - ft) * 255)); image(prevReflBuf, 0, 0);    noTint();
        tint(255, round(ft * 255));       image(reflectionBuf, 0, 0);  noTint();
      } else {
        image(reflectionBuf, 0, 0);
      }
    }

  } catch (e) {
    console.error(e);
  }
  drawingContext.restore();

  // モーションボックスは円マスクで切り取られないよう、ここで描画する
  if (vidReady) drawMotionEffect();

  if (textBuf) image(textBuf, 0, 0);

  // FPS 表示は不要のため削除
}

// 上から下へ伸びる粒子の表現（円・三角・四角）
function drawBottomParticles() {
  push();
  randomSeed(456);
  noFill();
  strokeWeight(0.8);
  stroke(0);

  const cx = width / 2;
  const count = 300;

  for (let i = 0; i < count; i++) {
    // y は画面全体に均等分布（上から下へ）
    const t = random();           // 0=上端, 1=下端
    const y = lerp(0, height, t);

    // x は中心から外側へ、上ほど狭く下ほど広がる（垂れ落ちる形）
    const spreadX = lerp(width * 0.38, width * 0.04, t);
    const x = cx + random(-spreadX, spreadX);

    // 下ほど大粒、上ほど小粒
    const sz = lerp(7.0, 0.8, t) + random(-0.3, 0.3);
    const half = sz / 2;
    const shape = floor(random(3));
    const rot = random(TWO_PI);
    const c = cos(rot);
    const s = sin(rot);

    if (shape === 0) {
      circle(x, y, sz);
    } else if (shape === 1) {
      quad(
        x + (-half)*c - (-half)*s, y + (-half)*s + (-half)*c,
        x + ( half)*c - (-half)*s, y + ( half)*s + (-half)*c,
        x + ( half)*c - ( half)*s, y + ( half)*s + ( half)*c,
        x + (-half)*c - ( half)*s, y + (-half)*s + ( half)*c
      );
    } else {
      const h2 = sz * 0.866;
      triangle(
        x,           y - h2 / 2,
        x - half,    y + h2 / 2,
        x + half,    y + h2 / 2
      );
    }
  }
  pop();
}

// 建物。display() で上=建物 / 下=反射 を同じ点描で描く
class Bs {
  constructor(cx) {
    // 円の幅に均等配置。幅はスロットより広めで多少重なる
    this.w = random(26, 46);
    this.x = cx - this.w / 2; // 左端
    const ch = sqrt(max(0, MASK_R * MASK_R - cx * cx)); // その位置での円の半分の高さ
    this.h = ch * random(0.6, 1.05);
    this.c = random(colors);
    this.c2 = random(colors);
    this.hasWindows = random([true, false]);
    this.windows = random([0, 1, 2, 2, 3, 3, 3, 4, 4, 5]);
    this.rows = random([4, 5, 6, 7, 8]);
  }

  // dir: -1=上（建物） / 1=下（反射）
  // sampler: null ならパレット色 / 関数なら (x,y)->色 をサンプル
  display(g, dir, sampler) {
    // 反射（静止画 = sampler あり）は点を少し増やしてはっきり見せる
    const bodyDots = floor(this.w * this.h * (sampler ? 0.7 : 0.5));
    for (let i = 0; i < bodyDots; i++) {
      const dx = this.x + random(this.w);
      const dy = dir * random(this.h);
      const c = sampler ? sampler(dx, dy) : this.c;
      g.fill(c[0], c[1], c[2], 40);
      g.circle(dx, dy, abs(randomGaussian(1.4, 0.65)));
    }
    if (this.hasWindows) {
      for (let j = 0; j < this.windows; j++) {
        for (let k = 0; k < this.rows; k++) {
          const d1 = this.w / (this.windows + 1);
          const d2 = this.h / this.rows;
          const wx0 = this.x + d1 / 2 + d1 * j;
          const ww = d1 / 2;
          const wh = d2 / 2;
          // 反射（静止画）の窓は点を増やして見やすく
          const winDots = floor(ww * wh * (sampler ? 1.8 : 1.2));
          for (let m = 0; m < winDots; m++) {
            const wx = wx0 + random(ww);
            // 上: y ∈ [-d2/2-d2k, -d2k] / 下: その鏡像
            const wy =
              dir < 0
                ? -d2 / 2 - d2 * k + random(wh)
                : d2 * k + random(wh);
            const c = sampler ? sampler(wx, wy) : this.c2;
            // 反射（静止画）の窓は不透明度を上げ、密度とともにはっきり見せる
            g.fill(c[0], c[1], c[2], sampler ? 150 : 90);
            g.circle(wx, wy, abs(randomGaussian(1.1, 0.55)));
          }
        }
      }
    }
  }
}

// ピンク系（または水色系）とグレー系で構成したパレット。呼ぶたびに交互
function newColors() {
  usePink = !usePink; // 今回の色味へ切り替え（ピンク ⇄ 水色）
  colors = [];
  for (let i = 0; i < 48; i++) {
    if (random() < 0.62) {
      if (usePink) {
        // 蛍光寄りのビビッドピンク
        colors.push([random(235, 255), random(25, 95), random(125, 180)]);
      } else {
        // 蛍光寄りのビビッド水色
        colors.push([random(60, 130), random(200, 245), random(235, 255)]);
      }
    } else {
      // グレー系
      const g = random(80, 160);
      colors.push([g, g, g]);
    }
  }
}

// change ボタン：街・色・反射を作り直す（旧クリック動作の置き換え）
function regenerate() {
  generateCity();
  if (vidReady) {
    captureStill(); // 再生中の動画の現在フレームを新しい静止画にする
    buildReflection();
  }
  buildStatic();
  redraw();
}

function keyPressed() {
  if (keyCode === 83) {
    save(cnv, "city", "png");
  }
  if (key === 'f' || key === 'F') {
    let fs = fullscreen();
    fullscreen(!fs);
  }
}
